import{_ as a,c as i,o as e,K as t,cl as n,cm as r,cn as p,co as l,cp as h}from"./chunks/framework.CqUzgkEo.js";const m=JSON.parse('{"title":"ED25519","description":"","frontmatter":{"title":"ED25519","date":"2021-09-17T00:00:00.000Z","tags":["ECC","Ed25519"]},"headers":[],"relativePath":"posts/ed25519.md","filePath":"posts/ed25519.md","lastUpdated":1783637320000}'),k={name:"posts/ed25519.md"};function o(E,s,d,c,g,u){return e(),i("div",null,[...s[0]||(s[0]=[t('<p>안녕하세요 Mambo 입니다.</p><p>오늘은 보안 관련 기술인 타원곡선 암호 알고리즘을 기반으로 하는 <strong>ED25519</strong>라는 것에 대해 알아보려고 합니다.</p><p>아마존 웹 서비스에서는 2021년 8월 17일부터 EC2 인스턴스 접근을 위해 <a href="https://aws.amazon.com/about-aws/whats-new/2021/08/amazon-ec2-customers-ed25519-keys-authentication/" target="_blank" rel="noreferrer">ED25519 형식의 키로 SSH 연결을 수행할 수 있도록 지원</a>하였으며 2021년 9월 1일에는 깃허브에서도 DSA 형식의 키를 제거하고 <a href="https://github.blog/2021-09-01-improving-git-protocol-security-github/" target="_blank" rel="noreferrer">ECDSA와 ED25519 형식의 키를 추가</a>하기로 결정하였습니다.</p><p>공통으로 언급되고 있는 ED25519라는 것을 모르시는 분이라면 저와 함께 알아보도록 합시다.</p><p><img src="'+n+'" alt=""></p><h2 id="ed25519" tabindex="-1">ED25519 <a class="header-anchor" href="#ed25519" aria-label="Permalink to “ED25519”">​</a></h2><p>ED25519(Ed25519)는 ECC(Elliptic Curve Cryptography) 알고리즘으로 수행하도록 구현된 전자서명입니다. 타원곡선 암호 알고리즘을 사용하는 공개키 암호화 방식은 <strong>기존의 RSA와 비교해서 동일한 안정성을 가지면서도 상대적으로 더 적은 길이의 키</strong>를 가진다고 합니다. 컴퓨터 연산 속도가 발전함에 따라 일반적으로 사용되는 RSA의 권장되는 키 길이가 길어짐으로 인하여 일반 컴퓨터 또는 디바이스에서는 연산 속도가 느려지는 단점을 가지게 되고 상대적으로 작은 키 길이를 사용할 수 있으면서 동일한 안정성을 보여주므로 권장되는 공개키 암호화 방식이라고 할 수 있습니다.</p><blockquote><p>RSA와 비교해서 보안적으로 우수하다고 볼 순 없지만 상대적으로 비교하여 효율적이라는 것을 이해하셔야합니다.</p></blockquote><h3 id="타원-곡선" tabindex="-1">타원 곡선 <a class="header-anchor" href="#타원-곡선" aria-label="Permalink to “타원 곡선”">​</a></h3><p>ED25519는 어떤 타원 곡선을 사용하여 구현된 전자서명일지 궁금해집니다. 다음은 암호화에 적합하다고 판단되어 표준으로 정의된 타원 곡선들입니다.</p><ul><li>secp256k1</li><li>secp256r1</li><li>prime256v1</li><li>Curve25519</li></ul><p>미국 국립표준연구소(NIST) 또는 <a href="https://www.secg.org/" target="_blank" rel="noreferrer">표준 암호화 그룹(SECG)</a>에서는 효율적인 타원 곡선들에 이름을 부여했습니다. 예를 들어, ECC NIST P-256은 SECG에서 정의한 secp256r1과 prime256v1를 지칭한 것과 같습니다.</p><p>표준으로 정의된 다양한 타원 곡선들에 대한 자세한 내용은 다음의 두 문서를 통해 확인할 수 있습니다.</p><ul><li><a href="https://www.secg.org/sec2-v2.pdf" target="_blank" rel="noreferrer">SEC 2: Recommended Elliptic Curve Domain Parameters</a></li><li><a href="https://nvlpubs.nist.gov/nistpubs/FIPS/NIST.FIPS.186-4.pdf" target="_blank" rel="noreferrer">Digital Signature Standard (DSS)</a></li></ul><p>저로서는 이해하기 힘든 부분이라고 생각하여 설명은 생략하며 간단하게 말해서 여러가지 타원 곡선 형태를 <strong>도메인 파라미터로 정의</strong>하여 이름을 부여한 것 입니다. NIST P-256은 NIST에서 정의한 소수 기반의 타원 곡선 방정식을 말하며 <a href="https://en.bitcoin.it/wiki/Secp256k1" target="_blank" rel="noreferrer">secp256k1</a>는 SECG에서 정의한 Koblitz curve 기반의 타원 곡선 방정식을 말합니다.</p><blockquote><p>비트코인과 이더리움에서도 secp256k1 라는 타원곡선을 사용한다고...</p></blockquote><h3 id="키-교환과-전자-서명" tabindex="-1">키 교환과 전자 서명 <a class="header-anchor" href="#키-교환과-전자-서명" aria-label="Permalink to “키 교환과 전자 서명”">​</a></h3><p>타원 곡선을 사용하여 디피-헬먼 키 교환을 구현한 알고리즘을 ECDH라고 하며 타원 곡선 암호를 사용해서 <a href="https://ko.wikipedia.org/wiki/%EB%94%94%EC%A7%80%ED%84%B8_%EC%84%9C%EB%AA%85_%EC%95%8C%EA%B3%A0%EB%A6%AC%EC%A6%98" target="_blank" rel="noreferrer">전자서명 알고리즘(DSA)</a>를 구현한 것을 <strong>ECDSA</strong>라고 합니다. ECDSA는 지난 <a href="./ssl-certificate">SSL 인증서</a> 글에서 TLS 핸드쉐이크 과정에서 ECDHE_ECDSA와 같은 타원 곡선 암호 방식을 사용하는 것을 통해 이미 확인한 개념인데 기억하시는 분이 계실지 모르겠습니다.</p><p>타원 곡선 기반의 전자 서명 알고리즘에는 <a href="https://en.wikipedia.org/wiki/EdDSA" target="_blank" rel="noreferrer">EdDSA</a>도 있으며 <strong>Twisted Edwards curve</strong>와 <strong>Schnorr 서명 방식</strong>을 사용하도록 구현된 DSA 입니다.</p><h3 id="x25519-그리고-ed25519" tabindex="-1">X25519 그리고 Ed25519 <a class="header-anchor" href="#x25519-그리고-ed25519" aria-label="Permalink to “X25519 그리고 Ed25519”">​</a></h3><p>앞서 언급된 타원 곡선 중 Curve25519는 키 교환 알고리즘인 디피-헬먼과 같이 사용하도록 고안된 타원 곡선입니다. Curve25519를 기반으로하여 ECDH로 키 교환을 수행하는 것을 X25519라고 하게 됩니다. 그리고 Curve25519과 함께 SHA-512와 같은 <strong>해시 함수</strong>를 사용하는 구현된 EdDSA를 <strong>Ed25519</strong>라는 이름으로 부르게 됩니다.</p><ul><li>ECDSA : 타원 곡선 기반의 전자 서명 알고리즘</li><li>X25519 : Curve25519를 사용하는 타원 곡선 키 교환 알고리즘</li><li>Ed25519 : Curve25519를 사용하는 타원 곡선 전자 서명 알고리즘</li></ul><p><img src="'+r+'" alt="머리속에 정리가 잘 되셨나요?"></p><h3 id="ed25519-키-페어" tabindex="-1">ED25519 키 페어 <a class="header-anchor" href="#ed25519-키-페어" aria-label="Permalink to “ED25519 키 페어”">​</a></h3><p>지금부터는 ED25519 형식의 키 페어를 만들고 EC2 인스턴스에 접근해보는 것을 따라해보겠습니다.</p><h4 id="키-페어-생성하기" tabindex="-1">키 페어 생성하기 <a class="header-anchor" href="#키-페어-생성하기" aria-label="Permalink to “키 페어 생성하기”">​</a></h4><p>먼저, ED25519 형식의 키 페어는 OpenSSH를 통해 만들 수도 있고 아마존 웹 서비스를 통해 ED25519 형식의 키 페어를 생성할 수 있습니다.</p><p><img src="'+p+`" alt=""></p><blockquote><p>2021년 8월 17일 부터는 콘솔을 통해 ED25119 키 페어를 사용하여 EC2 인스턴스 연결이 가능하다고 했는데 우측 제약사항에는 아직 업데이트되지 않은 듯 합니다.</p></blockquote><p>아래와 같이 AWS CLI의 create-key-pair 명령어를 통해서도 ED25519 키 페어를 생성할 수 있습니다.</p><div class="language-ps"><button title="Copy Code" class="copy"></button><span class="lang">ps</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">aws ec2 create</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pair </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">name mambo </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">type ed25519 </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">--</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">query </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;KeyMaterial&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> --</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">output text </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> aws</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">mambo.pem</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">aws ec2 describe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">key</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pairs</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">    &quot;KeyPairs&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        {</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;KeyPairId&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;###&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;KeyFingerprint&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;###&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;KeyName&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;mambo&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;KeyType&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;ed25519&quot;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">,</span></span>
<span class="line"><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">            &quot;Tags&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: []</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>아마존 웹 서비스에 키 페어가 생성되었으면 VPC에 EC2 인스턴스를 시작할 때 SSH 접속 시 사용될 ED25519 키 페어를 선택할 수 있습니다.</p><p><img src="`+l+'" alt=""></p><p>EC2 인스턴스가 실행되었으면 아마존 웹 서비스 콘솔의 EC2 인스턴스 연결 기능을 통해 인스턴스에 접속해보겠습니다.</p><p><img src="'+h+`" alt=""></p><p>ED25519 키 페어를 사용해서 EC2 인스턴스 연결에 성공하였습니다. 그런데 말이죠, 아마존 웹 서비스에서 생성된 ED25519 키 페어를 윈도우 10에서 지원하는 SSH 클라이언트에서 사용해보면 잘못된 형식이라고 로그가 출력되고 EC2 인스턴스에 연결할 수 없음을 확인했습니다.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh -i &quot;aws-mambo.pem&quot; ec2-user@ec2-3-36-96-111.ap-northeast-2.compute.amazonaws.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span>The authenticity of host &#39;ec2-3-36-96-111.ap-northeast-2.compute.amazonaws.com (3.36.96.111)&#39; can&#39;t be established.</span></span>
<span class="line"><span>ECDSA key fingerprint is SHA256:gvSJ/qfnIlB8bkTE78QY65HO4px3YpoYvsyAv90LsTE.</span></span>
<span class="line"><span>Are you sure you want to continue connecting (yes/no)? yes</span></span>
<span class="line"><span>Warning: Permanently added &#39;ec2-3-36-96-111.ap-northeast-2.compute.amazonaws.com,3.36.96.111&#39; (ECDSA) to the list of known hosts.</span></span>
<span class="line"><span>Load key &quot;aws-mambo.pem&quot;: invalid format</span></span>
<span class="line"><span>ec2-user@ec2-3-36-96-111.ap-northeast-2.compute.amazonaws.com: Permission denied (publickey,gssapi-keyex,gssapi-with-mic).</span></span></code></pre></div><p>아마존 웹 서비스가 만들어주는 ED25519 형식의 키 페어를 사용하지 않고 직접 윈도우 10에서 ssh-keygen을 통해 ED25519 형식의 키 페어를 생성하고 아마존 웹 서비스에 퍼블릭 키를 추가하면 정상적으로 EC2 인스턴스 연결할 수 있습니다.</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ssh-keygen -t ed25519 -m PEM -f ./mambo.pem</span></span></code></pre></div><p>이처럼 아마존 웹 서비스에서 만들어주는 ED25519 형식의 키 페어는 윈도우에서 사용할 수 없기 때문에 주의해야할 것 같습니다.</p><p>타원곡선 암호에 대해서 더 자세히 알고 싶다면 다음의 글들을 참고해보시기를 추천드립니다.</p><ul><li><a href="https://medium.com/humanscape-tech/blockchain-elliptic-curve-cryptography-ecc-49e6d7d9a50a" target="_blank" rel="noreferrer">[Blockchain] Elliptic Curve Cryptography(ECC)</a></li><li><a href="https://naleejang.tistory.com/218" target="_blank" rel="noreferrer">보안 그리고 암호화 알고리즘</a></li></ul><p>감사합니다.</p><h2 id="참고" tabindex="-1">참고 <a class="header-anchor" href="#참고" aria-label="Permalink to “참고”">​</a></h2><ul><li><a href="https://datatracker.ietf.org/doc/html/rfc4492" target="_blank" rel="noreferrer">Elliptic Curve Cryptography (ECC) Cipher Suites for Transport Layer Security (TLS)</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc7748" target="_blank" rel="noreferrer">Elliptic Curves for Security</a></li><li><a href="https://datatracker.ietf.org/doc/html/rfc8032" target="_blank" rel="noreferrer">Edwards-Curve Digital Signature Algorithm (EdDSA)</a></li><li><a href="https://ed25519.cr.yp.to/" target="_blank" rel="noreferrer">Ed25519: high-speed high-security signatures</a></li></ul>`,45)])])}const C=a(k,[["render",o]]);export{m as __pageData,C as default};
